#!/usr/bin/env bash
# Radiant documentation site: C# API reference generated by tools/Radiant.DocGen plus docs/*.md.
#
#   eng/docs.sh            dev server with live regeneration on C#/Markdown edits (http://localhost:5180)
#   eng/docs.sh build      static site in docs/site/dist
#   eng/docs.sh preview    build, then serve docs/site/dist
#
# Extra arguments are passed to Vite, e.g. `eng/docs.sh dev --host` to expose it on the network.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
site="$root/docs/site"
mode="${1:-dev}"
[ $# -gt 0 ] && shift

command -v dotnet >/dev/null || { echo "docs: the .NET SDK is required (dotnet not found)." >&2; exit 1; }
command -v pnpm >/dev/null || { echo "docs: pnpm is required (npm install -g pnpm, or corepack enable)." >&2; exit 1; }

# Package assets let DocGen resolve and link package types; restore once if missing.
[ -f "$root/obj/project.assets.json" ] || dotnet restore "$root/radiant.csproj" --verbosity quiet

if [ ! -d "$site/node_modules" ] || [ "$site/pnpm-lock.yaml" -nt "$site/node_modules/.modules.yaml" ]; then
  pnpm --dir "$site" install --frozen-lockfile
fi

case "$mode" in
  dev) exec pnpm --dir "$site" dev --open "$@" ;;
  build) exec pnpm --dir "$site" build "$@" ;;
  preview) pnpm --dir "$site" build && exec pnpm --dir "$site" preview --open "$@" ;;
  *) echo "usage: eng/docs.sh [dev|build|preview] [vite options]" >&2; exit 2 ;;
esac
